try { 
    const apiKey = env.get("API_KEY"); 
    if (!apiKey)
        return [
            null,
            null,
            {
                ...msg,
                statusCode: 500,
                payload: { status : 500, error: 'Server Error' }
            }
        ]; 

    const receivedKey = msg.req?.headers?.['x-api-key']; 
    if (receivedKey !== apiKey) 
        return [
            null, 
            null, 
            { 
                ...msg,
                statusCode: 401, 
                payload: { status: 401, error: 'Unauthorized' } 
            }
            ]; 

    const event = msg.payload?.data?.event; 
    if (!event) 
        return 
        [
            null, 
            { 
                ...msg,
                statusCode: 400, 
                payload: { status : 400, error: 'Invalid or empty event params' } 
            }, 
            null
        ];

    msg.payload = {
        event: event,
        state: msg.payload?.data?.state,
        value: msg.payload?.data?.value,
        unit: msg.payload?.data?.unit,
        sensor_id: msg.payload?.sensor_id
    }

    return [
        [msg], 
        null, 
        null
        ]; 
