    const fileName = fullPath.split("/").pop();
    const raw = fileName.replace(/\.mp4$/i, "");
    const parts = raw.split("_");

    if (parts.length >= 4) {
        const d = parts[0]; // ddMMyy
        const t = parts[1]; // hhmmss
        const dateStr = `${d.slice(0, 2)}/${d.slice(2, 4)}/20${d.slice(4, 6)}`;
