function fromPayload(p) {
  if (typeof p === 'string') {
    const text = p.trim()
    if (text.startsWith('{')) {
      try { p = JSON.parse(text) } catch { p = text }
    }
    else {
      p = text
    }
  }
  if (p && typeof p === 'object') {
    return p.recording_id || p.recordingId
  }
  return p
}

