// Helper: Format Timestamp ke ISO 8601 dengan offset +07:00 (WIB)
function toWIBIsoString(dateInput) {
    const d = dateInput ? new Date(dateInput) : new Date();
    const tzOffsetMs = 7 * 60 * 60 * 1000; // +07:00
    const localTime = new Date(d.getTime() + tzOffsetMs);
    return localTime.toISOString().replace("Z", "+07:00");
}

// Helper: Generate Batch ID unik (contoh: b-20261118-001)
function generateBatchId() {
    const now = new Date(Date.now() + 7 * 60 * 60 * 1000);
    const dateStr = now.toISOString().slice(0, 10).replace(/-/g, "");
    const seq = (flow.get("telemetry_batch_seq") || 0) + 1;
    flow.set("telemetry_batch_seq", seq);
    return `b-${dateStr}-${String(seq).padStart(3, "0")}`;
}

const nowIso = toWIBIsoString();

// 4. Mapping array incoming ke format readings (maksimal 1.000 item per batch)
const MAX_BATCH = 1000;
const readings = incoming.slice(0, MAX_BATCH).map(item => ({
    "sensor": item.sensor_id,
    "ts": item.timestamp,
    "value": Number(item.value),
    "quality": "good"
}));

// Peringatan jika data masuk melebihi 1.000 reading
if (incoming.length > MAX_BATCH) {
    node.warn(`Data melebihi ${MAX_BATCH} reading (${incoming.length}). Hanya 1.000 item pertama yang dikirim.`);
}

// 5. Susun Request Body & Backup ke msg.event
const body = {
    "batch_id": generateBatchId(),
    "device_ts": nowIso,
    "readings": readings
};

msg.payload = body;

return msg;

msg.sensor_type = "current";
msg.data_count = 100;
return msg;

msg.payload = msg.payload
    .map(item => ({
        value: item.value,
        // Replace space with 'T' for standard ISO-8601 parsing (append 'Z' if timestamps are UTC)
        timestamp: new Date(item.created_at.replace(' ', 'T')).getTime()
    }))
    .reverse(); // Optional: sorts chronologically (oldest to newest) for charts
msg.batch = true;
msg.topic = true;
return msg;

const results = Array.isArray(msg.payload?.results) ? msg.payload.results : [];
const firstTs = results.length > 0 ? Number(results[0].timestamp) : Date.now();

// Kunci urutan series agar warna selalu: 1=Biru, 2=Oranye, 3=Merah
const chartData = [
  { series: "current", value: null, timestamp: firstTs },
  { series: "warning", value: null, timestamp: firstTs },
  { series: "critical", value: null, timestamp: firstTs }
];

const maxStat = msg.payload?.statistics?.max;
const markerHeight = maxStat ? Math.ceil(maxStat * 1.1) : 1000;

results.forEach((item) => {
  const ts = Number(item.timestamp);

  // 1. Garis data utama
  chartData.push({
    series: "current",
    value: item.value,
    timestamp: ts
  });

  // 2. Penanda vertikal terputus (tanpa garis mendatar di y = 0)
  if (item.isAnomaly) {
    const seriesName = item.severity === "critical" ? "critical" : "warning";

    chartData.push({ series: seriesName, value: 0, timestamp: ts - 1 });
    chartData.push({ series: seriesName, value: markerHeight, timestamp: ts });
    chartData.push({ series: seriesName, value: 0, timestamp: ts + 1 });
    chartData.push({ series: seriesName, value: null, timestamp: ts + 2 }); // Pemutus garis
  }
});

msg.payload = chartData;
msg.action = "replace";
return msg;

const mapState = (item) => {
    // Prioritas pengecekan value 0 atau null
    if (item.value === 0) {
        return "CURRENT_ANOMALY_ZERO";
    }
    if (item.series === "critical") {
        return "CURRENT_ANOMALY_CRITICAL";
    }
    if (item.series === "warning") {
        return "CURRENT_ANOMALY_WARNING";
    }
    return "CURRENT_NORMAL";
};

// get last data point
if (msg.payload.length > 0) {
    msg.payload = msg.payload[msg.payload.length - 1]; 
}

msg.payload = 
{
    event: "current",
    state: mapState(msg.payload),
    value: msg.payload.value,
    unit: "mA",
    sensor_id: "AmpPhase1",
    timestamp: new Date(Number(msg.payload.timestamp)).toISOString()
}
return msg;

function toWIBIsoString(dateInput) {
    const d = dateInput ? new Date(dateInput) : new Date();
    const tzOffsetMs = 7 * 60 * 60 * 1000; // +07:00
    const localTime = new Date(d.getTime() + tzOffsetMs);
    return localTime.toISOString().replace("Z", "+07:00");
}

msg.payload.timestamp = toWIBIsoString(new Date());
return msg;
